      volatile long count = 0;
     const int PPR = 600;  // pulses per rotation          ― Interrupt ensures accurate counting
     void setup() {                  ― Direction determined using Channel B      pinMode(2, INPUT_PULLUP);
      pinMode(3, INPUT_PULLUP);              ― Used in precise motion control
       attachInterrupt(digitalPinToInterrupt(2), encoderISR, RISING);
       Serial.begin(9600);                ― Output give the number of rotation (1
       }                                                    rotation is equal to 600 PPR)     void loop() {
       float rotations;
       noInterrupts();
      rotations = (float)count / PPR;
       interrupts();
       Serial.print("Rotations: ");
       Serial.println((int)rotations);
      delay(50);
       }
     void encoderISR() {
          if (digitalRead(3) == HIGH) count++;
       else count--;
       }

